            v[10] = v[0] * v[8] + v[6] * v[9];
            v[6] = 1.22464679914735e-16 * v[0] + v[6];
            v[11] = 1.22464679914735e-16 * v[10] + v[7] + -4.44089209850063e-16 * v[6];
            v[12] = cos(x[2]);
            v[13] = sin(x[2]);
            v[14] = -1. * v[12] + 6.16297582203915e-32 * v[13];
            v[15] = 1.22464679914735e-16 * v[12] + 4.44089209850063e-16 * v[13];
            v[16] = v[10] * v[14] + v[7] * v[15] + v[6] * v[13];
            v[17] = sin(x[3]);
            v[18] = -v[17];
            v[19] = -v[13];
